// A 16 bit PCM WAV of a sine: `seconds` at `rate`, mono or stereo.
inline std::vector<uint8_t> sineWav(uint32_t rate = 8000, double seconds = 0.1, int channels = 1)
{
    const uint32_t frames = static_cast<uint32_t>(rate * seconds);
    std::vector<uint8_t> w;
    const auto put32 = [&](uint32_t v) { for (int i = 0; i < 4; ++i) w.push_back(static_cast<uint8_t>(v >> (8 * i))); };
    const auto put16 = [&](uint16_t v) { w.push_back(static_cast<uint8_t>(v)); w.push_back(static_cast<uint8_t>(v >> 8)); };
    const auto tag = [&](const char *t) { w.insert(w.end(), t, t + 4); };
    tag("RIFF"); put32(36 + frames * channels * 2); tag("WAVE"); tag("fmt "); put32(16); put16(1); put16(static_cast<uint16_t>(channels)); put32(rate);
    put32(rate * channels * 2); put16(static_cast<uint16_t>(channels * 2)); put16(16); tag("data"); put32(frames * channels * 2);
    for (uint32_t i = 0; i < frames; ++i) {
        const int16_t v = static_cast<int16_t>(12000.0 * std::sin(2.0 * 3.14159265358979 * 440.0 * i / rate));
        for (int c = 0; c < channels; ++c) put16(static_cast<uint16_t>(v));
    }
    return w;
}

